import { MakeLogicType, afterMount, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import type { InsightsFlow } from './insightsflows/types'

export interface WorkflowNameLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowNameLogicValues {
    workflow: InsightsFlow | null
    workflowLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowNameLogicActions {
    loadWorkflow: () => any
    loadWorkflowFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadWorkflowSuccess: (
        workflow: InsightsFlow | null,
        payload?: any
    ) => {
        workflow: InsightsFlow | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowNameLogicMeta {
    key: string
}

export type workflowNameLogicType = MakeLogicType<
    workflowNameLogicValues,
    workflowNameLogicActions,
    WorkflowNameLogicProps,
    workflowNameLogicMeta
>

/**
 * Resolves one workflow by id, for places that need its current name without owning a list.
 * Keyed by id, so several rows citing the same workflow share a single request, and reading it
 * can't be perturbed by the filters or pagination of the workflows list scene.
 */
export const workflowNameLogic = kea<workflowNameLogicType>([
    props({} as WorkflowNameLogicProps),
    key((props) => props.id),
    path((key) => ['products', 'workflows', 'frontend', 'workflowNameLogic', key]),
    loaders(({ props }) => ({
        workflow: [
            null as InsightsFlow | null,
            {
                loadWorkflow: async () => {
                    try {
                        return await api.hogFlows.getInsightsFlow(props.id)
                    } catch {
                        // Deleted, or not visible to this user. Callers fall back to a generic label.
                        return null
                    }
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadWorkflow()
    }),
])
